# bash completion for enconvert                            -*- shell-script -*-
# Generated by `enconvert completion bash`. Fully static: no network calls,
# no callbacks into the CLI. Regenerate after upgrading enconvert.

_enconvert_known_path() {
  case "$1" in
    "convert"|"data"|"compress"|"pdf"|"markdown"|"url"|"url pdf"|"url screenshot"|"url markdown"|"site"|"site pdf"|"site screenshot"|"perceive"|"perceive get"|"perceive batch"|"perceive batch get"|"perceive batch cancel"|"discover"|"lookup"|"distill"|"ingest"|"ingest create"|"ingest files"|"ingest list"|"ingest get"|"ingest cancel"|"ingest retry-webhook"|"ingest webhook-secret"|"ingest webhook-secret show"|"ingest webhook-secret rotate"|"jobs"|"jobs get"|"jobs batch"|"jobs wait"|"files"|"files download"|"formats"|"params"|"params convert"|"whoami"|"status"|"usage"|"version"|"docs"|"open"|"auth"|"auth login"|"auth logout"|"auth status"|"auth token"|"auth switch"|"config"|"config get"|"config set"|"config unset"|"config list"|"config edit"|"config path"|"config debug"|"api"|"completion"|"upgrade"|"mcp"|"mcp install"|"mcp uninstall"|"mcp list"|"help") return 0 ;;
  esac
  return 1
}

_enconvert() {
  local cur prev
  COMPREPLY=()
  cur="${COMP_WORDS[COMP_CWORD]}"
  prev="${COMP_WORDS[COMP_CWORD-1]}"

  # Resolve the subcommand path, skipping flags (and, implicitly, flag
  # values and positionals: only known subcommand names extend the path).
  local path="" candidate="" w="" i
  for ((i = 1; i < COMP_CWORD; i++)); do
    w="${COMP_WORDS[i]}"
    case "$w" in -*) continue ;; esac
    if [ -z "$path" ]; then candidate="$w"; else candidate="$path $w"; fi
    if _enconvert_known_path "$candidate"; then path="$candidate"; fi
  done

  # Value suggestions for the flag before the cursor.
  case "$path|$prev" in
    "|--color")
      COMPREPLY=( $(compgen -W "auto always never" -- "$cur") )
      return ;;
    "convert|--to"|"convert|-t")
      COMPREPLY=( $(compgen -W "csv heic html jpeg json md pdf png svg toml webp xml yaml" -- "$cur") )
      return ;;
    "convert|--from")
      COMPREPLY=( $(compgen -W "bmp csv doc docx epub gif heic heif htm html jpeg jpg json markdown md mdown mkd numbers odp ods odt ots pages pdf png ppt pptx rtf svg text tif tiff toml txt webp xhtml xls xlsx xml yaml yml" -- "$cur") )
      return ;;
    "convert|--endpoint")
      COMPREPLY=( $(compgen -W "anything-to-markdown anything-to-pdf compress-image csv-to-json csv-to-xml doc-to-pdf excel-to-pdf heic-to-jpeg heic-to-png heic-to-svg heic-to-webp html-to-pdf jpeg-to-heic jpeg-to-png jpeg-to-svg jpeg-to-webp json-to-csv json-to-toml json-to-xml json-to-yaml markdown-to-html markdown-to-pdf numbers-to-pdf odp-to-pdf ods-to-pdf odt-to-pdf ots-to-pdf pages-to-pdf pdf-to-jpeg png-to-heic png-to-jpeg png-to-svg png-to-webp ppt-to-pdf svg-to-heic svg-to-jpeg svg-to-png svg-to-webp toml-to-json webp-to-heic webp-to-jpeg webp-to-png webp-to-svg xml-to-csv xml-to-json yaml-to-json" -- "$cur") )
      return ;;
    "convert|--pdf-orientation")
      COMPREPLY=( $(compgen -W "portrait landscape" -- "$cur") )
      return ;;
    "data|--to"|"data|-t")
      COMPREPLY=( $(compgen -W "csv heic html jpeg json md pdf png svg toml webp xml yaml" -- "$cur") )
      return ;;
    "pdf|--pdf-orientation")
      COMPREPLY=( $(compgen -W "portrait landscape" -- "$cur") )
      return ;;
    "url pdf|--pdf-orientation")
      COMPREPLY=( $(compgen -W "portrait landscape" -- "$cur") )
      return ;;
    "url markdown|--pdf-orientation")
      COMPREPLY=( $(compgen -W "portrait landscape" -- "$cur") )
      return ;;
    "site pdf|--crawl-mode")
      COMPREPLY=( $(compgen -W "auto sitemap full" -- "$cur") )
      return ;;
    "site screenshot|--crawl-mode")
      COMPREPLY=( $(compgen -W "auto sitemap full" -- "$cur") )
      return ;;
    "perceive|--cache-mode")
      COMPREPLY=( $(compgen -W "enabled bypass refresh" -- "$cur") )
      return ;;
    "perceive|--pdf-orientation")
      COMPREPLY=( $(compgen -W "portrait landscape" -- "$cur") )
      return ;;
    "perceive batch|--output-mode")
      COMPREPLY=( $(compgen -W "manifest zip" -- "$cur") )
      return ;;
    "perceive batch|--cache-mode")
      COMPREPLY=( $(compgen -W "enabled bypass refresh" -- "$cur") )
      return ;;
    "perceive batch|--pdf-orientation")
      COMPREPLY=( $(compgen -W "portrait landscape" -- "$cur") )
      return ;;
    "discover|--mode")
      COMPREPLY=( $(compgen -W "sitemap crawl hybrid" -- "$cur") )
      return ;;
    "discover|--render-js")
      COMPREPLY=( $(compgen -W "auto never always" -- "$cur") )
      return ;;
    "lookup|--category")
      COMPREPLY=( $(compgen -W "web news images scholar patents maps" -- "$cur") )
      return ;;
    "lookup|--time-filter")
      COMPREPLY=( $(compgen -W "hour day week month year" -- "$cur") )
      return ;;
    "distill|--discover-mode")
      COMPREPLY=( $(compgen -W "sitemap crawl hybrid" -- "$cur") )
      return ;;
    "ingest create|--mode")
      COMPREPLY=( $(compgen -W "urls sitemap crawl" -- "$cur") )
      return ;;
    "formats|--from")
      COMPREPLY=( $(compgen -W "bmp csv doc docx epub gif heic heif htm html jpeg jpg json markdown md mdown mkd numbers odp ods odt ots pages pdf png ppt pptx rtf svg text tif tiff toml txt webp xhtml xls xlsx xml yaml yml" -- "$cur") )
      return ;;
    "formats|--to")
      COMPREPLY=( $(compgen -W "csv heic html jpeg json md pdf png svg toml webp xml yaml" -- "$cur") )
      return ;;
    "params convert|--from")
      COMPREPLY=( $(compgen -W "bmp csv doc docx epub gif heic heif htm html jpeg jpg json markdown md mdown mkd numbers odp ods odt ots pages pdf png ppt pptx rtf svg text tif tiff toml txt webp xhtml xls xlsx xml yaml yml" -- "$cur") )
      return ;;
    "params convert|--to")
      COMPREPLY=( $(compgen -W "csv heic html jpeg json md pdf png svg toml webp xml yaml" -- "$cur") )
      return ;;
  esac

  local subs="" flags=""
  case "$path" in
    "")
      subs="convert data compress pdf markdown url site perceive discover lookup distill ingest jobs files formats params whoami status usage version docs open auth config api completion upgrade mcp help"
      flags="--version -V --verbose -v --debug --quiet -q --json --jsonl --jq --template --color --no-color --no-progress --yes -y --force -F --skip-existing --dry-run -n --no-input --config --profile -p --api-key --api-url --timeout --retries --concurrency -j --help -h"
      ;;
    "convert")
      subs=""
      flags="--to -t --from --endpoint --output -o --output-dir -O --url-only --output-filename --job-id --pdf-page-size --pdf-orientation --pdf-margin --pdf-scale --pdf-grayscale --pdf-header --pdf-footer --pdf-header-height --pdf-footer-height --pdf-page-width --pdf-page-height --width --height --target-size-kb --help -h"
      ;;
    "data")
      subs=""
      flags="--to -t --output -o --output-dir -O --url-only --output-filename --job-id --help -h"
      ;;
    "compress")
      subs=""
      flags="--target-size-kb --output -o --output-dir -O --url-only --output-filename --job-id --help -h"
      ;;
    "pdf")
      subs=""
      flags="--output -o --output-dir -O --url-only --output-filename --job-id --pdf-page-size --pdf-orientation --pdf-margin --pdf-scale --pdf-grayscale --pdf-header --pdf-footer --pdf-header-height --pdf-footer-height --pdf-page-width --pdf-page-height --help -h"
      ;;
    "markdown")
      subs=""
