      flags="--output -o --output-dir -O --viewport-width --viewport-height --wait-for-selector --wait-for-selector-timeout --load-media --no-load-media --enable-scroll --no-enable-scroll --sticky-header --no-sticky-header --handle-cookies --no-handle-cookies --wait-for-images --no-wait-for-images --block-ads --block-media --basic-auth --cookie --header --notification-email --callback-url --output-filename --job-id --async --no-async --zip --single-page --no-single-page --pdf-page-size --pdf-orientation --pdf-margin --pdf-scale --pdf-grayscale --pdf-header --pdf-footer --pdf-header-height --pdf-footer-height --pdf-page-width --pdf-page-height --wait --no-wait --poll-interval --wait-timeout --exit-status --url-only --help -h"
      ;;
    "url screenshot")
      subs=""
      flags="--output -o --output-dir -O --viewport-width --viewport-height --wait-for-selector --wait-for-selector-timeout --load-media --no-load-media --enable-scroll --no-enable-scroll --sticky-header --no-sticky-header --handle-cookies --no-handle-cookies --wait-for-images --no-wait-for-images --block-ads --block-media --basic-auth --cookie --header --notification-email --callback-url --output-filename --job-id --async --no-async --zip --wait --no-wait --poll-interval --wait-timeout --exit-status --url-only --help -h"
      ;;
