      ;;
    "site")
      subs="pdf screenshot"
      flags="--help -h"
      ;;
    "site pdf")
      subs=""
      flags="--crawl-mode --include-pattern --exclude-pattern --output -o --output-dir -O --viewport-width --viewport-height --wait-for-selector --wait-for-selector-timeout --load-media --no-load-media --enable-scroll --no-enable-scroll --sticky-header --no-sticky-header --handle-cookies --no-handle-cookies --wait-for-images --no-wait-for-images --block-ads --block-media --basic-auth --cookie --header --notification-email --callback-url --output-filename --job-id --wait --no-wait --poll-interval --wait-timeout --exit-status --url-only --help -h"
      ;;
    "site screenshot")
      subs=""
      flags="--crawl-mode --include-pattern --exclude-pattern --output -o --output-dir -O --viewport-width --viewport-height --wait-for-selector --wait-for-selector-timeout --load-media --no-load-media --enable-scroll --no-enable-scroll --sticky-header --no-sticky-header --handle-cookies --no-handle-cookies --wait-for-images --no-wait-for-images --block-ads --block-media --basic-auth --cookie --header --notification-email --callback-url --output-filename --job-id --wait --no-wait --poll-interval --wait-timeout --exit-status --url-only --help -h"
      ;;
    "perceive")
      subs="get batch"
      flags="--output-dir -O --url-only --output --extract --schema-file --wait-for --wait-timeout-ms --js-code --viewport --mobile --respect-robots --cache-mode --block-resource --header --cookie --basic-auth --pdf-page-size --pdf-orientation --pdf-margin --pdf-scale --pdf-grayscale --pdf-header --pdf-footer --pdf-header-height --pdf-footer-height --pdf-page-width --pdf-page-height --help -h"
      ;;
