      ;;
    "discover")
      subs=""
      flags="--mode --max-urls --max-depth --include-pattern --exclude-pattern --same-domain-only --no-same-domain-only --respect-robots --render-js --help -h"
      ;;
    "lookup")
      subs=""
      flags="--category --country --locale --time-filter --num-results --page --location --no-autocorrect --perceive-top --enrich-output --enrich-concurrency --enrich-schema-file --synthesize-answer --answer-prompt --help -h"
